import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

task_binary_join = verify('task_binary_join', '''
    use core.thread;
    fn worker() -> i32 {
        return 1
    }
    fn main() -> i32 {
        let left = spawn(worker)
        let right = spawn(worker)
        return join(left) + join(right)
    }
''', 0)
assert task_binary_join['errors'] == 0, task_binary_join

websocket_wrapper = verify('websocket_wrapper', '''
    use core.http;
    fn close_ws(ws: WebSocketHandle) -> i32 {
        return http.websocket_close(ws, 1000, "ok")
    }
    fn main() -> i32 {
        let listener = http.bind("127.0.0.1:8787")
        defer close(listener)
        let conn = http.accept()
        let ws = http.websocket_accept(conn)
        discard close_ws(ws)
        return 0
    }
''', 0)
assert websocket_wrapper['errors'] == 0, websocket_wrapper
assert not any('linear value `ws` was not consumed/freed' in message for message in messages(websocket_wrapper)), websocket_wrapper

process_wrapper = verify('process_wrapper', '''
    use core.proc;
    fn close_wrapper(handle: ProcessHandle) -> i32 {
        return proc.close(handle)
    }
    fn main() -> i32 {
        let argv = proc.argv_new()
        let env = proc.env_new()
        let handle = proc.spawn_cmd("echo", argv, env, "")
        discard close_wrapper(handle)
        return 0
    }
''', 0)
assert process_wrapper['errors'] == 0, process_wrapper
assert not any('linear value `handle` was not consumed/freed' in message for message in messages(process_wrapper)), process_wrapper

stream_param = verify('stream_param', '''
    use core.http;
    fn inspect(stream: HttpStreamHandle) -> i32 {
        if http.stream_eof(stream) == 1 {
            return 1
        }
        discard http.stream_status(stream)
        return 0
    }
''', 0)
assert stream_param['errors'] == 0, stream_param
assert not any('linear value `stream` was not consumed/freed' in message for message in messages(stream_param)), stream_param

http_conn_transfer = verify('http_conn_transfer', '''
    use core.http;
    fn respond(conn: HttpHandle) -> i32 {
        return http.write_json(conn, 200, "{\"ok\":true}")
    }
    fn main() -> i32 {
        let conn = http.accept()
        discard respond(conn)
        return 0
    }
''', 0)
assert http_conn_transfer['errors'] == 0, http_conn_transfer
assert not any('function `respond` linear value `conn` was not consumed/freed' in message for message in messages(http_conn_transfer)), http_conn_transfer

loop_conn = verify('loop_conn', '''
    use core.http;
    fn main() -> i32 {
        let mut served = 0
        while served < 2 {
            let conn = http.accept()
            discard http.write_json(conn, 200, "{\"ok\":true}")
            served = served + 1
        }
        return 0
    }
''', 0)
assert loop_conn['errors'] == 0, loop_conn
assert not any('divergent ownership state for `conn`' in message for message in messages(loop_conn)), loop_conn

print('compiler-memory-runtime-handles-ok')

